import json, urllib.request, urllib.error
from pathlib import Path
mcp = json.loads(Path("/Users/bastionii/Documents/Github/whatsapp-crm/.cursor/mcp.json").read_text())
cfg = mcp["mcpServers"]["coolify"]
base = cfg["url"].removesuffix("/mcp")
token = cfg["headers"]["Authorization"].split(" ", 1)[1]
app = "qdhnhxzz3robqagljnxcwnj2"

def parse_env(path):
    out = {}
    for line in Path(path).read_text().splitlines():
        line=line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k,v=line.split("=",1)
        out[k]=v
    return out

def call(method, path, body):
    r = urllib.request.Request(base+"/api/v1"+path, data=json.dumps(body).encode(), method=method, headers={
        "Authorization": f"Bearer {token}", "Accept":"application/json", "Content-Type":"application/json", "User-Agent":"Mozilla/5.0",
    })
    try:
        with urllib.request.urlopen(r) as res:
            data=json.loads(res.read().decode())
            print(res.status, "preview", body["is_preview"], "buildtime", data.get("is_buildtime"), "runtime", data.get("is_runtime"))
    except urllib.error.HTTPError as e:
        print(e.code, e.read().decode()[:200])

value = "production"
for preview in (False, True):
    call("PATCH", f"/applications/{app}/envs", {
        "key": "NODE_ENV",
        "value": value,
        "is_preview": preview,
        "is_literal": True,
        "is_runtime": True,
        "is_buildtime": False,
    })
