import json
from pathlib import Path
hits = []
for p in Path("node_modules").rglob("package.json"):
    if ".bun" in p.parts and p.parent.name != "node_modules":
        # only the package's own package.json: .../node_modules/<name>/package.json or .bun/pkg/node_modules/name/package.json
        pass
    try:
        data = json.loads(p.read_text())
    except Exception:
        continue
    deps = {}
    for field in ("dependencies", "optionalDependencies", "peerDependencies"):
        deps.update(data.get(field) or {})
    name = data.get("name") or ""
    wanted = [d for d in deps if d in {"react-native", "expo", "react-native-reanimated"} or d.startswith("expo-")]
    if wanted and name not in wanted and not name.startswith("expo") and "react-native" not in name:
        hits.append((name, wanted, str(p)[:120]))
print("dependents", len(hits))
for row in hits[:40]:
    print(row[0], row[1])
