import os
from pathlib import Path
root = Path("node_modules/.bun")
sizes = []
if root.exists():
    for p in root.iterdir():
        total = 0
        for dirpath, dirs, files in os.walk(p):
            for f in files:
                try:
                    total += os.path.getsize(os.path.join(dirpath, f))
                except OSError:
                    pass
        sizes.append((total, p.name))
sizes.sort(reverse=True)
print("largest packages:")
for total, name in sizes[:25]:
    print(f"{total/1e6:8.1f} MB  {name[:80]}")
print("count", len(sizes), "sum_mb", round(sum(s for s,_ in sizes)/1e6,1))
